<?php
require_once __DIR__ . '/../lib/bootstrap.php';$token=preg_replace('/[^a-f0-9]/','',(string)($_GET['token']??''));$s=db()->prepare('SELECT a.*,e.title exam_title,e.total_score,u.full_name student_name,s.title subject_title FROM report_shares r JOIN attempts a ON a.id=r.attempt_id JOIN exams e ON e.id=a.exam_id JOIN users u ON u.id=a.student_id JOIN subjects s ON s.id=e.subject_id WHERE r.token=? AND (r.expires_at IS NULL OR r.expires_at>NOW())');$s->execute([$token]);$r=$s->fetch();if(!$r)exit('لینک گزارش نامعتبر یا منقضی شده است.');$s=db()->prepare('SELECT q.question_text,q.score,a.awarded_score,a.is_correct FROM answers a JOIN questions q ON q.id=a.question_id WHERE a.attempt_id=? ORDER BY q.sort_order');$s->execute([$r['id']]);$answers=$s->fetchAll();$title='گزارش اشتراکی';require __DIR__.'/../partials/header.php';?><div class="card"><h1>گزارش نتیجه آزمون</h1><p>دانش‌آموز: <?=e($r['student_name'])?> | آزمون: <?=e($r['exam_title'])?> | درس: <?=e($r['subject_title'])?></p><div class="grid grid-2"><div><strong>نمره:</strong> <?=format_score($r['score'])?> از <?=format_score($r['total_score'])?></div><div><strong>درصد:</strong> <?=format_score($r['percentage'])?>%</div></div></div><div class="card"><h2>تحلیل پرسش‌ها</h2><table class="table"><thead><tr><th>پرسش</th><th>نمره</th><th>وضعیت</th></tr></thead><tbody><?php foreach($answers as $a):?><tr><td><?=e($a['question_text'])?></td><td><?=format_score($a['awarded_score']??0)?> / <?=format_score($a['score'])?></td><td><?=((int)$a['is_correct']===1?'صحیح':((int)$a['is_correct']===0?'نادرست':'نیازمند بررسی'))?></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../partials/footer.php'; ?>
